import { assetUrl } from "@/site/assetUrl";

/**
 * Entries for the homepage "APTCODER in the Spotlight" strip.
 *
 * Every image was matched by looking at it, not by its filename, and every online entry was
 * checked against the live page. Nothing here is guessed: where a newspaper masthead or date
 * is not visible in a cutting, the field is left out rather than filled in.
 *
 * - "image" entries open full size in the on-page press viewer (`fullImage`).
 * - "online" entries open the original article in a new tab (`articleUrl`).
 *
 * Thumbnails in public/News/thumbs are generated by scripts/build-news-thumbnails.py.
 */

type NewsEntryBase = {
  id: string;
  /** Who published it. Shown prominently on the card and in the viewer. */
  publicationName: string;
  /** Small label describing what kind of coverage it is. */
  kind: string;
  headline: string;
  /** Human-readable date, only when it is stated in the source itself. */
  publicationDate?: string;
  /** Card thumbnail, or null when no matching image exists (a text card is shown instead). */
  thumbnail: string | null;
  thumbnailAlt: string;
  /** CSS object-position for the card crop, so the meaningful part of the image shows. */
  thumbnailPosition?: string;
  description: string;
};

export type ImageNewsEntry = NewsEntryBase & {
  type: "image";
  fullImage: string;
  fullImageWidth: number;
  fullImageHeight: number;
};

export type OnlineNewsEntry = NewsEntryBase & {
  type: "online";
  articleUrl: string;
};

export type NewsEntry = ImageNewsEntry | OnlineNewsEntry;

/** Files in public/News have spaces in their names; encode them for use as URLs. */
const newsFile = (name: string) => assetUrl(`/News/${encodeURIComponent(name)}`);

